entries[44502] = { ["name"] = "Schematic: Mechano-Hog", ["text"] = "Binds when picked up\nRequires Engineering (450)\nRequires Horde Expedition\n- Exalted\nUse: Teaches you how to make a Mechano-Hog.\nSell Price:\nMechano-Hog\nMount\nRequires any Horde race\nRequires Level 40\nRequires Journeyman Riding\nUse: Teaches you how to ride this sweet hog.\nRides and parks a badass Mechano-Hog.\nSell Price:\nRequires Titansteel Bar (12), Handful of Cobalt Bolts (40), Arctic Fur (2), Salvaged Iron Golem Parts , Goblin-Machined Piston (8), Elementium-Plated Exhaust Pipe" }
