entries[44862] = { ["name"] = "Recipe: Pumpkin Pie", ["text"] = "Binds when picked up\nRequires Cooking (100)\nUse: Teaches you how to bake Pumpkin Pie.\n\nPumpkin Pie\nRequires Pilgrim's Bounty\nUse: Restores 4% of your health and mana every sec for 30 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain [floor(cond([source value]( 85, 15), 85 - 15, 0) * 0.554) + 4] Spirit and Stamina for 1 hour.\nSell Price:\nRequires Ripe Elwynn Pumpkin , Honey", ["unresolvedValues"] = true }
